 70→/**
 71→ * Format a timestamp for display.
 72→ * Within current year: "Feb 24". Older: "Feb 24, 2025". Falsy: "".
 73→ */
 74→function formatRelativeDate(timestamp: number): string {
 75→  if (!timestamp) return '';
 76→
 77→  const date = new Date(timestamp);
 78→  const now = new Date();
 79→  const months = [
 80→    'Jan',
 81→    'Feb',
 82→    'Mar',
 83→    'Apr',
 84→    'May',
 85→    'Jun',
 86→    'Jul',
 87→    'Aug',
 88→    'Sep',
 89→    'Oct',
 90→    'Nov',
 91→    'Dec',
 92→  ];
 93→
 94→  const month = months[date.getMonth()];
 95→  const day = date.getDate();
 96→
 97→  if (date.getFullYear() === now.getFullYear()) {
 98→    return `${month} ${day}`;
 99→  }
100→  return `${month} ${day}, ${date.getFullYear()}`;
101→}
