103→/**
104→ * Highlight matching substrings in a name using MiniSearch match info.
105→ * Falls back to rendering the name without highlights if match info is unavailable.
106→ */
107→function highlightMatches(name: string, match: Record<string, string[]>): ReactNode {
108→  // Collect matched terms from the 'name' field
109→  const terms = match?.name ?? [];
110→  if (terms.length === 0) return name;
111→
112→  // Build a set of character indices that are part of a match
113→  const matchedIndices = new Set<number>();
114→  const lower = name.toLowerCase();
115→
116→  for (const term of terms) {
117→    const termLower = term.toLowerCase();
118→    let startPos = 0;
119→    // Find all occurrences of the term in the name
120→    while (startPos < lower.length) {
121→      const idx = lower.indexOf(termLower, startPos);
122→      if (idx === -1) break;
123→      for (let i = idx; i < idx + termLower.length; i++) {
124→        matchedIndices.add(i);
125→      }
126→      startPos = idx + 1;
127→    }
128→  }
129→
130→  if (matchedIndices.size === 0) return name;
131→
132→  // Build segments: consecutive matched/unmatched characters
133→  const segments: ReactNode[] = [];
134→  let i = 0;
135→  while (i < name.length) {
136→    const isMatch = matchedIndices.has(i);
137→    let j = i;
138→    while (j < name.length && matchedIndices.has(j) === isMatch) {
139→      j++;
140→    }
141→    const segment = name.slice(i, j);
142→    if (isMatch) {
143→      segments.push(<mark key={i}>{segment}</mark>);
144→    } else {
145→      segments.push(segment);
146→    }
147→    i = j;
148→  }
149→
150→  return <>{segments}</>;
151→}
