157→function SearchResultItem({
158→  result,
159→  isSelected,
160→  onClick,
161→  onMouseEnter,
162→}: {
163→  result: SearchResult;
164→  isSelected: boolean;
165→  onClick: () => void;
166→  onMouseEnter: () => void;
167→}) {
168→  const icon = getFileIcon(result.name, result.type);
169→  const dateStr = formatRelativeDate(result.modifiedAt);
170→  const highlightedName = highlightMatches(result.name, result.match);
171→
172→  return (
173→    <div
174→      className={`search-result-item ${isSelected ? 'selected' : ''}`}
175→      onClick={onClick}
176→      onMouseEnter={onMouseEnter}
177→      role="option"
178→      aria-selected={isSelected}
179→    >
180→      <span className={`search-result-icon ${isSelected ? 'icon-bright' : ''}`}>{icon}</span>
181→      <div className="search-result-info">
182→        <span className="search-result-name">{highlightedName}</span>
183→        <span className="search-result-path">{result.parentPath}</span>
184→      </div>
185→      {dateStr && <span className="search-result-date">{dateStr}</span>}
186→    </div>
187→  );
188→}
