194→interface SearchPaletteProps {
195→  isOpen: boolean;
196→  query: string;
197→  onQueryChange: (q: string) => void;
198→  results: SearchResult[];
199→  resultCount: number;
200→  isBuilding: boolean;
201→  isIndexReady: boolean;
202→  onClose: () => void;
203→  onSelectResult: (result: SearchResult) => void;
204→}
205→
206→/**
207→ * Command palette overlay for searching files and folders.
208→ *
209→ * Keyboard-first design: arrow keys navigate results, Enter opens,
210→ * Escape closes. Click outside backdrop also dismisses.
211→ *
212→ * Terminal aesthetic: JetBrains Mono, green on black, sharp corners.
213→ */
214→export function SearchPalette({
215→  isOpen,
216→  query,
217→  onQueryChange,
218→  results,
219→  resultCount,
220→  isBuilding,
221→  isIndexReady,
222→  onClose,
223→  onSelectResult,
224→}: SearchPaletteProps) {
225→  const [selectedIndex, setSelectedIndex] = useState(0);
226→  const inputRef = useRef<HTMLInputElement>(null);
227→  const resultsRef = useRef<HTMLDivElement>(null);
228→  const backdropRef = useRef<HTMLDivElement>(null);
229→
230→  // Reset selection when results change
231→  useEffect(() => setSelectedIndex(0), [results]);
232→
233→  // Focus input when opening
234→  useEffect(() => {
235→    if (isOpen) inputRef.current?.focus();
236→  }, [isOpen]);
237→
238→  // Scroll selected item into view
239→  useEffect(() => {
240→    const container = resultsRef.current;
241→    if (!container) return;
242→    const selected = container.children[selectedIndex] as HTMLElement | undefined;
243→    selected?.scrollIntoView({ block: 'nearest' });
244→  }, [selectedIndex]);
245→
246→  // Keyboard navigation
247→  const handleKeyDown = (e: React.KeyboardEvent) => {
248→    switch (e.key) {
249→      case 'ArrowDown':
250→        e.preventDefault();
251→        setSelectedIndex((i) => Math.min(i + 1, results.length - 1));
252→        break;
253→      case 'ArrowUp':
254→        e.preventDefault();
255→        setSelectedIndex((i) => Math.max(i - 1, 0));
256→        break;
257→      case 'Enter':
258→        e.preventDefault();
259→        if (results[selectedIndex]) {
260→          onSelectResult(results[selectedIndex]);
261→        }
262→        break;
263→      case 'Escape':
264→        e.preventDefault();
265→        onClose();
266→        break;
267→    }
268→  };
269→
270→  // Click outside to close
271→  const handleBackdropClick = (e: React.MouseEvent) => {
272→    if (e.target === backdropRef.current) onClose();
273→  };
274→
275→  if (!isOpen) return null;
276→
277→  return (
278→    <div
279→      className="search-backdrop"
280→      ref={backdropRef}
281→      onClick={handleBackdropClick}
282→      role="dialog"
283→      aria-modal="true"
284→      aria-label="Search files"
285→    >
286→      <div className="search-palette" onKeyDown={handleKeyDown}>
287→        {/* Search input */}
288→        <div className="search-input-row">
289→          <span className="search-icon">&gt;_</span>
290→          <input
291→            ref={inputRef}
292→            className="search-input"
293→            type="text"
294→            placeholder="Search files..."
295→            value={query}
296→            onChange={(e) => onQueryChange(e.target.value)}
297→            autoComplete="off"
298→            spellCheck={false}
299→          />
300→          <span className="search-esc-hint">ESC</span>
301→        </div>
302→
303→        {/* Results area */}
304→        <div className="search-results" ref={resultsRef} role="listbox" aria-label="Search results">
305→          {isBuilding && <div className="search-building">{'// building index...'}</div>}
306→          {!isBuilding && isIndexReady && query.trim() && results.length === 0 && (
307→            <div className="search-no-results">
308→              {"// no results for '"}
309→              {query}
310→              {"'"}
311→            </div>
312→          )}
313→          {results.map((result, index) => (
314→            <SearchResultItem
315→              key={result.id}
316→              result={result}
317→              isSelected={index === selectedIndex}
318→              onClick={() => onSelectResult(result)}
319→              onMouseEnter={() => setSelectedIndex(index)}
320→            />
321→          ))}
322→        </div>
323→
324→        {/* Footer with keyboard hints and result count */}
325→        <div className="search-footer">
326→          <span className="search-footer-hints">
327→            <kbd>{'\u2191\u2193'}</kbd> navigate <kbd>{'\u21B5'}</kbd> open <kbd>esc</kbd> close
328→          </span>
329→          {resultCount > 0 && (
330→            <span className="search-footer-count">
331→              {'// '}
332→              {resultCount} result{resultCount !== 1 ? 's' : ''}
333→            </span>
334→          )}
335→        </div>
336→      </div>
337→    </div>
338→  );
339→}
